import API from "./api";


// 🧑‍⚕️ Get all doctors
export const getAllDoctors = () => {
  return API.get(`${base}/doctors`);
};

// 🔍 Get doctor by ID
export const getDoctorById = (id) => {
  return API.get(`${API_BASE_URL}/doctors/${id}`);
};

// ➕ Add doctor (ADMIN)
export const addDoctor = (data) => {
  return API.post(`${API_BASE_URL}/doctors`, data);
};

// ✏️ Update doctor
export const updateDoctor = (id, data) => {
  return API.put(`${API_BASE_URL}/doctors/${id}`, data);
};

// ❌ Delete doctor
export const deleteDoctor = (id) => {
  return API.delete(`${API_BASE_URL}/doctors/${id}`);
};
